export async function callFrameRpc<Request, Response>(
  method: string,
  rpc: UnaryRpc<Request, Response>,
  request: Request,
  correlationId: string = randomUUID(),
  retryUnavailable = false,
): Promise<Response> {
  const metadata = new Metadata()
  metadata.set('x-correlation-id', correlationId)
  const rpcLogger = logger.child({ correlationId })
  const startedAt = performance.now()
  const deadline = Date.now() + TIMEOUT_MS
  const call = () =>
    new Promise<Response>((resolve, reject) => {
      rpc(request, metadata, { deadline }, (error, response) => {
        if (error) {
          reject(error)
        } else if (!response) {
          reject(new Error('gRPC returned no response'))
        } else {
          resolve(response)
        }
      })
    })

  try {
    const response = retryUnavailable
      ? await readRetry.execute(call, AbortSignal.timeout(TIMEOUT_MS))
      : await call()
    rpcLogger.debug(
      { method, durationMs: performance.now() - startedAt },
      'Frame RPC completed',
    )
    return response
  } catch (error) {
    const durationMs = performance.now() - startedAt
    const grpcError = isGrpcError(error) ? error : undefined

    if (grpcError) {
      const code = clientErrorCodes.get(grpcError.code)
      if (code) {
        rpcLogger.debug(
          { method, grpcCode: grpcError.code, durationMs },
          'Frame RPC rejected',
        )
        const violations =
          grpcError.code === status.INVALID_ARGUMENT
            ? fieldViolations(error)
            : []
        throw new GraphQLError(grpcError.details, {
          extensions: {
            code,
            ...(violations.length > 0 ? { fieldViolations: violations } : {}),
          },
        })
      }

      if (
        grpcError.code === status.UNAVAILABLE ||
        grpcError.code === status.DEADLINE_EXCEEDED
      ) {
        rpcLogger.warn(
          { method, grpcCode: grpcError.code, durationMs },
          'Frame service is unavailable',
        )
        throw new GraphQLError('Frame service is unavailable', {
          extensions: { code: GRAPHQL_ERROR_CODES.SERVICE_UNAVAILABLE },
        })
      }
    }

    rpcLogger.error(
      { method, grpcCode: grpcError?.code, durationMs },
      'Frame RPC failed',
    )
    throw new GraphQLError('Frame operation failed', {
      extensions: { code: GRAPHQL_ERROR_CODES.INTERNAL_SERVER_ERROR },
    })
  }
}
'use client'

import { useEffect, useState } from 'react'

type HealthResponse = {
  status: string
  service: string
  timestamp: string
}

type FetchState =
  | { kind: 'loading' }
  | { kind: 'ok'; data: HealthResponse }
  | { kind: 'error'; message: string }

export default function Home() {
  const [state, setState] = useState<FetchState>({ kind: 'loading' })

  useEffect(() => {
    const controller = new AbortController()
    fetch('/api/health', { signal: controller.signal })
      .then(async (res) => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`)
        return (await res.json()) as HealthResponse
      })
      .then((data) => setState({ kind: 'ok', data }))
      .catch((err: unknown) => {
        if (err instanceof Error && err.name === 'AbortError') return
        const message = err instanceof Error ? err.message : 'Unknown error'
        setState({ kind: 'error', message })
      })
    return () => controller.abort()
  }, [])

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', padding: '2rem', maxWidth: 720, margin: '0 auto' }}>
      <h1>Take-home exercise</h1>
      <p>Frontend &harr; Backend smoke check</p>
      <section
        style={{
          padding: '1rem 1.25rem',
          border: '1px solid #ccc',
          borderRadius: 8,
          background: '#f7f7f7',
        }}
      >
        {state.kind === 'loading' && <span>Calling <code>/api/health</code>&hellip;</span>}
        {state.kind === 'error' && (
          <span style={{ color: '#b00020' }}>
            Backend unreachable: {state.message}
          </span>
        )}
        {state.kind === 'ok' && (
          <pre style={{ margin: 0 }}>{JSON.stringify(state.data, null, 2)}</pre>
        )}
      </section>
    </main>
  )
}
